import axios from 'axios';

const api = axios.create({
  baseURL: 'http://localhost:4000/api/v1/jokes/',
});

export const getRandomJoke = async () => {
  const response = await api.get('random');

  console.log("---")
  console.log(response.data)
  console.log("---")
  return response.data;
};
